#!/usr/bin/env node

/*
 * Fill tests/cases.json expected values from a workbook JSON generated by
 * tools/extract-workbook.cjs.
 *
 * Usage:
 *   node tools/generate-cases-from-workbook.cjs draft-pool.json tests/cases.json
 *   node tools/generate-cases-from-workbook.cjs draft-pool.json tests/cases.json out.json
 *
 * The script looks for a matching row inside workbook.composition using the
 * 5 selected champions. If a row is found, it writes the full normalized row
 * to expected and marks the case as validated.
 */

const fs = require('node:fs');
const path = require('node:path');

const REQUIRED_ROLES = ['top', 'jungle', 'mid', 'adc', 'support'];
const ROLE_ALIASES = {
  top: ['top', 'top lane', 'tope', 'role top'],
  jungle: ['jungle', 'jungla', 'jg', 'jng'],
  mid: ['mid', 'middle', 'mid lane', 'medio'],
  adc: ['adc', 'bot', 'botline', 'bottom', 'carry'],
  support: ['support', 'supp', 'sup', 'soporte'],
};

function fail(message) {
  console.error(message);
  process.exit(1);
}

function normalize(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/["'`´’]/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .toLowerCase();
}

function pickKey(row, aliases) {
  if (!row || typeof row !== 'object') return null;
  const entries = Object.entries(row);
  for (const alias of aliases) {
    const normalizedAlias = normalize(alias);
    const exact = entries.find(([key]) => normalize(key) === normalizedAlias);
    if (exact) return exact[0];
  }
  for (const [key] of entries) {
    const normalizedKey = normalize(key);
    if (aliases.some((alias) => normalizedKey === normalize(alias) || normalizedKey.includes(normalize(alias)))) {
      return key;
    }
  }
  return null;
}

function getRoleValue(row, role) {
  const key = pickKey(row, ROLE_ALIASES[role]);
  return key ? String(row[key] ?? '').trim() : '';
}

function matchCompositionRow(row, composition) {
  return REQUIRED_ROLES.every((role) => normalize(getRoleValue(row, role)) === normalize(composition[role]));
}

function cleanExpected(row) {
  if (!row || typeof row !== 'object') return {};
  const cleaned = {};
  for (const [key, value] of Object.entries(row)) {
    cleaned[String(key).trim()] = String(value ?? '').trim();
  }
  return cleaned;
}

function main() {
  const workbookJsonPath = process.argv[2];
  const casesJsonPath = process.argv[3] || path.resolve(process.cwd(), 'tests/cases.json');
  const outputPath = process.argv[4] || casesJsonPath;

  if (!workbookJsonPath) {
    fail('Usage: node tools/generate-cases-from-workbook.cjs draft-pool.json tests/cases.json [out.json]');
  }

  const resolvedWorkbook = path.resolve(process.cwd(), workbookJsonPath);
  const resolvedCases = path.resolve(process.cwd(), casesJsonPath);

  if (!fs.existsSync(resolvedWorkbook)) {
    fail(`Workbook JSON not found: ${resolvedWorkbook}`);
  }
  if (!fs.existsSync(resolvedCases)) {
    fail(`Cases JSON not found: ${resolvedCases}`);
  }

  const workbook = JSON.parse(fs.readFileSync(resolvedWorkbook, 'utf8'));
  const casesData = JSON.parse(fs.readFileSync(resolvedCases, 'utf8'));

  if (!Array.isArray(casesData)) {
    fail('tests/cases.json must be a JSON array.');
  }
  if (!Array.isArray(workbook.composition)) {
    fail('Workbook JSON must include a composition array.');
  }

  const updated = casesData.map((testCase) => {
    const composition = testCase?.composition || {};
    const match = workbook.composition.find((row) => matchCompositionRow(row, composition));

    if (!match) {
      return {
        ...testCase,
        expected: {
          ...testCase.expected,
          status: 'pending',
          reason: 'No matching composition row found in workbook JSON',
        },
      };
    }

    return {
      ...testCase,
      expected: {
        status: 'validated',
        compositionRow: cleanExpected(match),
      },
      notes: testCase.notes,
    };
  });

  const outJson = `${JSON.stringify(updated, null, 2)}\n`;
  fs.writeFileSync(path.resolve(process.cwd(), outputPath), outJson, 'utf8');
  console.log(`Wrote ${outputPath}`);
}

main();
